77	static bt_status_t parse_bt_adv_data(uint8_t* raw, uint16_t raw_len,
78	    struct bt_data* out, size_t out_max, size_t* out_size)
79	{
80	    size_t index;
81	    uint8_t item_len;
82	
83	    if (!out || !out_size || out_max == 0) {
84	        return BT_STATUS_PARM_INVALID;
85	    }
86	
87	    *out_size = 0;
88	
89	    if (!raw || raw_len == 0) {
90	        return BT_STATUS_SUCCESS;
91	    }
92	
93	    for (index = 0; index < raw_len;) {
94	        item_len = raw[index];
95	        if (item_len == 0) {
96	            break;
97	        }
98	
99	        if (item_len < 2) {
100	            BT_LOGE("%s, invalid adv data item len:%d", __func__, item_len);
101	            return BT_STATUS_PARM_INVALID;
102	        }
103	
104	        if (index + 1 + item_len > raw_len) {
105	            BT_LOGE("%s, adv data overflow: raw_len=%d idx=%d item_len=%d", __func__,
106	                raw_len, index, item_len);
107	            return BT_STATUS_PARM_INVALID;
108	        }
109	
110	        if (*out_size >= out_max) {
111	            BT_LOGE("too many segments: out_max=%d idx=%d", out_max, index);
112	            return BT_STATUS_PARM_INVALID;
113	        }
114	
115	        out[*out_size].data_len = item_len - 1;
116	        out[*out_size].type = raw[index + 1];
117	        out[*out_size].data = &raw[index + 2];
118	        index += out[*out_size].data_len + 2;
119	        (*out_size)++;
120	    }
121	
122	    return BT_STATUS_SUCCESS;
123	}
